import {KebabHorizontalIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, Heading, IconButton, ProgressBar, Stack} from '@primer/react'
import {useEffect, useState} from 'react'

import styles from './SharedChecklistComponent.module.css'
import type {AnalyticsEntry, StepData} from './Stepper/Stepper'
import {Stepper} from './Stepper/Stepper'
import {useClickAnalytics} from '@github-ui/use-analytics'
import {handleSubmitFormAction} from './helpers/handle-submit-form-action'

export interface SharedChecklistComponentProps {
  /**
   * An array of step metadata describing each checklist item. Each entry is
   * a `StepData` object (title, description, CTA, analytics, etc.). The
   * ordering of this array determines the order rendered in the UI.
   */
  stepMetadata: StepData[]
  /**
   * Whether the checklist is currently dismissed/hidden. This is a
   * controlled prop: the component will render null when `dismissed` is
   * true. Use `onDismiss` to be notified of user dismiss actions.
   */
  dismissed: boolean
  /**
   * Optional callback invoked when the user dismisses the checklist. Use
   * this to persist the dismissed state in the parent if desired.
   */
  onDismiss?: () => void
  /**
   * An array of booleans that maps 1:1 to `stepMetadata` indicating which
   * steps are complete. This prop drives the displayed completion state
   * (controlled mode). To let the component manage completion internally,
   * pass an initial checklist and omit handling updates.
   */
  checklist: boolean[]
  /**
   * Callback invoked when the component updates the checklist (for
   * example, when a step is marked complete). Receives the new boolean
   * array. Use this in controlled scenarios to update parent state.
   */
  onChecklistChange?: (checklist: boolean[]) => void
  /**
   * Optional hook called when a step is completed. Receives the completed
   * step index. This is primarily a convenience for analytics or other
   * side-effects; the component also emits analytics via internal hooks.
   */
  trackStepComplete?: (index: number) => void
  /**
   * When true, renders a larger header style.
   * @default false
   */
  largeHeader?: boolean
  /**
   * When true, render styling suitable for use in a dashboard context
   * (spacing and margins).
   * @default false
   */
  dashboardChecklist?: boolean
  /**
   * Optional override text for the dismiss/remove action in the options
   * menu.
   * @default 'Remove'
   */
  dismissText?: string
  /**
   * Optional title text for the checklist header.
   * @default 'Getting started'
   */
  title?: string
}

export const SharedChecklistComponent = ({
  stepMetadata,
  dismissed,
  checklist,
  onDismiss,
  onChecklistChange,
  largeHeader,
  dashboardChecklist = false,
  trackStepComplete,
  dismissText = 'Remove',
  title = 'Getting started',
}: SharedChecklistComponentProps) => {
  const firstIncompleteIndex = checklist.findIndex(step => !step)
  const [activeStep, setActiveStep] = useState(firstIncompleteIndex !== -1 ? firstIncompleteIndex : 0)

  const populatedSteps = stepMetadata.map((step, i) => ({
    ...step,
    isComplete: checklist[i] ?? false,
  }))
  const [steps, setSteps] = useState(populatedSteps)
  const [isDismissed, setIsDismissed] = useState(dismissed)
  const [isUpdating, setIsUpdating] = useState(false)

  const {sendClickAnalyticsEvent} = useClickAnalytics()

  const dismissChecklist = () => {
    onDismiss?.()
    setIsDismissed(true)
  }

  const handleStepChange = (index: number) => {
    setActiveStep(index)
  }

  const sendAnalytics = (analytics?: AnalyticsEntry) => {
    if (!analytics) return
    sendClickAnalyticsEvent({category: analytics.category, action: analytics.action})
  }

  const handleStepButtonClick = (stepIndex: number, buttonIndex?: number, isCustom?: boolean) => {
    setIsUpdating(true)

    const step = buttonIndex === undefined ? steps[stepIndex] : steps[stepIndex]?.multipleCtaButtons?.[buttonIndex]

    if (!step) return

    if (!step.autoComplete && !step.isComplete) {
      setActiveStep(stepIndex + 1)
      setSteps(prev => prev.map((s, i) => (i === stepIndex ? {...s, isComplete: true} : s)))
      trackStepComplete?.(stepIndex)
    }

    sendAnalytics(step.analytics)

    if (step.href && !isCustom) {
      window.location.href = step.href
    } else if (step.formAction) {
      handleSubmitFormAction(step.formAction)
    }
  }

  useEffect(() => {
    if (!isUpdating) return

    onChecklistChange?.(steps.map(step => step.isComplete))
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setIsUpdating(false)
  }, [steps, isUpdating, onChecklistChange])

  if (isDismissed) return null

  return (
    <Stack
      direction="vertical"
      gap="normal"
      className={dashboardChecklist ? 'mb-3' : 'mt-3'}
      data-testid="checklist-component"
    >
      <Stack direction="horizontal" justify="space-between" align="center">
        <Heading id="checklist-heading" as="h2" className={`${styles.header} ${largeHeader ? styles.large : ''}`}>
          {title}
        </Heading>
        <Stack direction="horizontal" gap="condensed" align="center">
          <ProgressBar
            barSize="small"
            aria-hidden="true"
            progress={(steps.filter(step => step.isComplete).length / steps.length) * 100}
            className={styles.progressBar}
          />
          <span className={styles.progressText}>
            {steps.filter(step => step.isComplete).length}/{steps.length} complete
          </span>

          <ActionMenu>
            <ActionMenu.Anchor>
              <IconButton
                icon={KebabHorizontalIcon}
                aria-label="Remove section"
                variant="invisible"
                data-testid="checklist-options"
              />
            </ActionMenu.Anchor>
            <ActionMenu.Overlay align="end">
              <ActionList>
                <ActionList.Item onSelect={dismissChecklist} data-testid="checklist-remove-option">
                  {dismissText}
                </ActionList.Item>
              </ActionList>
            </ActionMenu.Overlay>
          </ActionMenu>
        </Stack>
      </Stack>
      <Stepper
        steps={steps}
        activeStepIndex={activeStep}
        onStepChange={handleStepChange}
        onStepButtonClick={handleStepButtonClick}
      />
    </Stack>
  )
}

try{ SharedChecklistComponent.displayName ||= 'SharedChecklistComponent' } catch {}